SELECT no_plan();
CREATE TEMP TABLE square_renewal_fixture(booking_id uuid,period_id uuid,guest_user uuid,admin_user uuid,other_user uuid,attempt jsonb,original_booking jsonb);
GRANT ALL ON square_renewal_fixture TO authenticated,service_role;
DO $$ DECLARE b public.bookings%ROWTYPE; actor uuid; guest uuid; other uuid; planned jsonb; period uuid; BEGIN
 SELECT * INTO b FROM public.bookings WHERE reservation_number='ZNX-000150';
 SELECT user_id INTO actor FROM public.profiles WHERE is_admin LIMIT 1;
 SELECT user_id INTO guest FROM public.profiles WHERE id=b.renter_profile_id;
 SELECT user_id INTO other FROM public.profiles WHERE id<>b.renter_profile_id AND NOT is_admin LIMIT 1;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true);
 planned:=public.admin_schedule_rental_extension(b.id,b.end_date+30,b.dropoff_time,158400,true,'Synthetic Square renewal test');
 PERFORM public.admin_activate_rental_extension((planned->>'plan_id')::uuid);
 SELECT id INTO period FROM public.rental_extension_periods WHERE extension_plan_id=(planned->>'plan_id')::uuid ORDER BY period_number LIMIT 1;
 INSERT INTO square_renewal_fixture SELECT b.id,period,guest,actor,other,NULL,to_jsonb(x) FROM public.bookings x WHERE x.id=b.id;
END $$;
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',other_user,'role','authenticated')::text,true) FROM square_renewal_fixture;
SET LOCAL ROLE authenticated;
SELECT throws_like('SELECT get_guest_renewal_details(period_id) FROM square_renewal_fixture','%different account%','Unrelated account cannot inspect');
SELECT throws_like('SELECT prepare_square_renewal_payment(period_id,guest_user,''live'',''location'') FROM square_renewal_fixture','%permission denied%','Browser cannot forge service payment claim');
RESET ROLE;
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',admin_user,'role','authenticated')::text,true) FROM square_renewal_fixture;
SET LOCAL ROLE authenticated;
SELECT is((SELECT get_guest_renewal_details(period_id)->>'admin_inspection' FROM square_renewal_fixture),'true','Authorized admin can inspect exact live terms');
SELECT is((SELECT get_guest_renewal_details(period_id)->>'can_pay' FROM square_renewal_fixture),'false','Admin inspection never enables charging');
SELECT is((SELECT get_guest_renewal_details(period_id)->>'amount_cents' FROM square_renewal_fixture),'158400','Inspection uses exact server-owned price');
SELECT throws_like('SELECT admin_prepare_renewal_payment(period_id) FROM square_renewal_fixture','%permission denied%','Legacy stored-card collection retired');
RESET ROLE;
SELECT is((SELECT count(*)::integer FROM square_renewal_payment_attempts),0,'Inspection creates no payment attempts');
SET LOCAL ROLE service_role;
SELECT throws_like('SELECT prepare_guest_renewal_checkout(period_id,guest_user,true) FROM square_renewal_fixture','%permission denied%','Prior hosted checkout retired');
SELECT throws_like('SELECT prepare_square_renewal_payment(period_id,admin_user,''live'',''location'') FROM square_renewal_fixture','%Only the reservation guest%','Admin cannot submit on behalf of guest');
UPDATE square_renewal_fixture SET attempt=prepare_square_renewal_payment(period_id,guest_user,'live','location');
SELECT is((SELECT attempt->>'dispatch' FROM square_renewal_fixture),'true','Only first guest submission may dispatch');
SELECT is((SELECT prepare_square_renewal_payment(period_id,guest_user,'live','location')->>'dispatch' FROM square_renewal_fixture),'false','Repeated submission cannot dispatch again');
SELECT throws_like('SELECT record_square_renewal_payment((attempt->>''id'')::uuid,''square-id'',1,''location'',''live'',''COMPLETED'') FROM square_renewal_fixture','%evidence conflicts%','Underpayment cannot settle');
SELECT record_square_renewal_payment((attempt->>'id')::uuid,'square-id',158400,'location','live','PENDING') FROM square_renewal_fixture;
SELECT is((SELECT payment_status FROM rental_extension_periods WHERE id=(SELECT period_id FROM square_renewal_fixture)),'processing','Pending payment is not paid');
SELECT ok((SELECT paid_at IS NULL FROM rental_extension_periods WHERE id=(SELECT period_id FROM square_renewal_fixture)),'Pending payment has no paid timestamp');
SELECT record_square_renewal_payment((attempt->>'id')::uuid,'square-id',158400,'location','live','COMPLETED') FROM square_renewal_fixture;
SELECT is((SELECT payment_status FROM rental_extension_periods WHERE id=(SELECT period_id FROM square_renewal_fixture)),'paid','Canonical completion settles renewal');
SELECT record_square_renewal_payment((attempt->>'id')::uuid,'square-id',158400,'location','live','COMPLETED') FROM square_renewal_fixture;
SELECT record_square_renewal_payment((attempt->>'id')::uuid,'square-id',158400,'location','live','FAILED') FROM square_renewal_fixture;
SELECT is((SELECT count(*)::integer FROM rental_extension_events WHERE period_id=(SELECT period_id FROM square_renewal_fixture) AND event_type='payment_succeeded'),1,'Exactly one success audit despite duplicates and late failure');
SELECT is((SELECT to_jsonb(b) FROM bookings b WHERE id=(SELECT booking_id FROM square_renewal_fixture)),(SELECT original_booking FROM square_renewal_fixture),'Original booking and deposit fields unchanged');
SELECT is((SELECT count(*)::integer FROM booking_payments),0,'Renewal creates no original rental charge');
SELECT is((SELECT count(*)::integer FROM booking_security_deposits),0,'Renewal creates no deposit');
RESET ROLE;
